const data = $input.first().json;
const usGaap = data.facts["us-gaap"];

function latestAnnualUsd(tag) {
  const rows = usGaap?.[tag]?.units?.USD ?? [];

  const latest = rows
    .filter(row => row.form === "10-K" && row.end)
    .sort(
      (a, b) =>
        b.end.localeCompare(a.end) ||
        (b.filed ?? "").localeCompare(a.filed ?? "")
    )[0];

  if (!latest) return null;

  return {
    valueUSD: latest.val,
    valueBillions: Number((latest.val / 1_000_000_000).toFixed(2)),
    periodEnded: latest.end,
    filed: latest.filed,
  };
}

return [
  {
    json: {
      company: data.entityName,
      cik: data.cik,
      source: "SEC EDGAR Company Facts",
      metrics: {
        revenue: latestAnnualUsd(
          "RevenueFromContractWithCustomerExcludingAssessedTax"
        ),
        netIncome: latestAnnualUsd("NetIncomeLoss"),
        totalAssets: latestAnnualUsd("Assets"),
      },
    },
  },
];

const raw = String($input.first().json.pageText ?? "");
const text = raw.replace(/\\n/g, " ").replace(/\s+/g, " ");

const revenue = text.match(/Revenue was \$([\d.]+) billion/i);
const netIncome = text.match(/Net income was \$([\d.]+) billion/i);
const quarterEnded = text.match(
  /quarter ended ([A-Z][a-z]+ \d{1,2}, \d{4})/i
);

// Read the exact current and prior-year amounts from the income statement.
const incomeStatement = text.match(
  /INCOME STATEMENTS([\s\S]*?)BALANCE SHEETS/i
);

if (!incomeStatement) {
  throw new Error("Could not find the income statement in pageText.");
}

const statement = incomeStatement[1];
const revenues = statement.match(
  /Total revenue\s+\$?([\d,]+)\s+\$?([\d,]+)/i
);
const netIncomes = statement.match(
  /Net income\s+\$?([\d,]+)\s+\$?([\d,]+)/i
);
const grossProfits = statement.match(
  /Gross margin\s+\$?([\d,]+)\s+\$?([\d,]+)/i
);
if (!revenue || !netIncome || !quarterEnded || !revenues || !netIncomes || !grossProfits) {
  throw new Error("Could not find all current and prior-year earnings figures.");
}

const currentRevenue = Number(revenues[1].replace(/,/g, "")) / 1000;
const priorRevenue = Number(revenues[2].replace(/,/g, "")) / 1000;
const currentNetIncome = Number(netIncomes[1].replace(/,/g, "")) / 1000;
const priorNetIncome = Number(netIncomes[2].replace(/,/g, "")) / 1000;
const currentGrossProfit = Number(grossProfits[1].replace(/,/g, "")) / 1000;
const priorGrossProfit = Number(grossProfits[2].replace(/,/g, "")) / 1000;

const currentGrossMarginPercent = Number(
  ((currentGrossProfit / currentRevenue) * 100).toFixed(2)
);
const priorGrossMarginPercent = Number(
  ((priorGrossProfit / priorRevenue) * 100).toFixed(2)
);
return [
  {
    json: {
      company: "Microsoft",
      source: "Microsoft Investor Relations",
      quarterEnded: quarterEnded[1],

      // Rounded headline figures, as before
      revenueBillions: Number(revenue[1]),
      netIncomeGaapBillions: Number(netIncome[1]),

      // Exact income statement figures, converted from millions to billions
      revenueCurrentExactBillions: currentRevenue,
      revenuePriorYearBillions: priorRevenue,
      netIncomeCurrentExactGaapBillions: currentNetIncome,
      netIncomePriorYearGaapBillions: priorNetIncome,
      grossProfitCurrentBillions: currentGrossProfit,
      grossProfitPriorYearBillions: priorGrossProfit,
      grossMarginPercentCurrent: currentGrossMarginPercent,
      grossMarginPercentPriorYear: priorGrossMarginPercent,
      grossMarginChangePercentagePoints: Number(
        (currentGrossMarginPercent - priorGrossMarginPercent).toFixed(2)
),
      // Compare Q1 FY27 with Q1 FY26
      revenueYoYGrowthPercent: Number(
        (((currentRevenue - priorRevenue) / priorRevenue) * 100).toFixed(2)
      ),
      netIncomeGaapYoYGrowthPercent: Number(
        (((currentNetIncome - priorNetIncome) / priorNetIncome) * 100).toFixed(2)
      ),

      note: "Growth calculated from exact income statement figures; Q1 compared with Q1",
    },
  },
];

return $input.all().map(item => {
  const data = item.json;

  let revenue;
  let netIncome;

  if (data.source === 'SEC EDGAR Company Facts') {
    revenue = data.metrics?.revenue?.valueUSD;
    netIncome = data.metrics?.netIncome?.valueUSD;
  } else if (data.source === 'Microsoft Investor Relations') {
    revenue = data.revenueBillions;
    netIncome = data.netIncomeGaapBillions;
  }

  const margin = Number.isFinite(Number(revenue)) &&
                 Number.isFinite(Number(netIncome))
    ? Number(((Number(netIncome) / Number(revenue)) * 100).toFixed(2))
    : null;

  return {
    json: {
      ...data,
      netIncomeMarginPercent: margin,
    },
  };
});

const records = $input.all().map(item => item.json);

const annual = records.find(
  item => item.source === "SEC EDGAR Company Facts"
);
const quarterly = records.find(
  item => item.source === "Microsoft Investor Relations"
);

if (!annual || !quarterly) {
  throw new Error("Expected both the SEC and Microsoft IR records.");
}

const exactQuarterlyNetMargin = Number(
  (
    (quarterly.netIncomeCurrentExactGaapBillions /
      quarterly.revenueCurrentExactBillions) * 100
  ).toFixed(2)
);

return [
  {
    json: {
      company: "Microsoft",
      annual: {
        source: annual.source,
        sourceUrl:
          "https://data.sec.gov/api/xbrl/companyfacts/CIK0000789019.json",
        periodEnded: annual.metrics.revenue.periodEnded,
        filed: annual.metrics.revenue.filed,
        revenueBillions: annual.metrics.revenue.valueBillions,
        netIncomeBillions: annual.metrics.netIncome.valueBillions,
        totalAssetsBillions: annual.metrics.totalAssets.valueBillions,
        netIncomeMarginPercent: annual.netIncomeMarginPercent
      },
      quarterly: {
        source: quarterly.source,
        sourceUrl:
          "https://www.microsoft.com/en-us/investor/earnings/fy-2027-q1/press-release-webcast",
        quarterEnded: quarterly.quarterEnded,
        revenueBillions: quarterly.revenueCurrentExactBillions,
        netIncomeGaapBillions:
          quarterly.netIncomeCurrentExactGaapBillions,
        grossProfitBillions:
          quarterly.grossProfitCurrentBillions,
        netIncomeMarginPercent: exactQuarterlyNetMargin,
        grossMarginPercent:
          quarterly.grossMarginPercentCurrent,
        revenueYoYGrowthPercent:
          quarterly.revenueYoYGrowthPercent,
        netIncomeGaapYoYGrowthPercent:
          quarterly.netIncomeGaapYoYGrowthPercent,
        grossMarginChangePercentagePoints:
          quarterly.grossMarginChangePercentagePoints
      },
      analysisLimits: [
        "Annual and quarterly totals cover different lengths of time; do not compare them as if they were the same period.",
        "This data does not include share price or company valuation.",
        "Summarize reported facts; do not make a buy or sell recommendation."
      ]
    }
  }
];
